package qpack_test

import (
	"encoding/hex"
	"encoding/json"
	"os"
	"path/filepath"
	"testing"

	codec "github.com/enetx/quic-go/internal/qpack"
	"github.com/stretchr/testify/require"
)

// These expected field sections and encoder bytes are from the original real
// browser captures, never generated by this encoder. Generic options and the
// SETTINGS event position live in the fixture; runtime code has no browser mode.
// Section ACKs model the captured peer's sequential decode/response progression.
func TestEncoderIndependentBrowserVectors(t *testing.T) {
	paths, err := filepath.Glob("testdata/browser/*.json")
	require.NoError(t, err)
	require.Len(t, paths, 8)
	for _, path := range paths {
		t.Run(filepath.Base(path), func(t *testing.T) {
			data, err := os.ReadFile(path)
			require.NoError(t, err)
			var fixture struct {
				Provenance     string               `json:"provenance"`
				PeerCapacity   uint64               `json:"peer_capacity"`
				Capacity       uint64               `json:"capacity"`
				Options        codec.EncoderOptions `json:"options"`
				SettingsBefore int                  `json:"settings_before_request"`
				SendCapacity   bool                 `json:"send_capacity"`
				EncoderStream  string               `json:"encoder_stream_hex"`
				Requests       []struct {
					StreamID uint64        `json:"stream_id"`
					Fields   []codec.Field `json:"fields"`
					Block    string        `json:"header_block_hex"`
				} `json:"requests"`
			}
			require.NoError(t, json.Unmarshal(data, &fixture))
			require.NotEmpty(t, fixture.Provenance)
			require.Len(t, fixture.Requests, 11)
			e := codec.NewEncoder(fixture.Options)
			instructions := make([]byte, 0)
			for i, request := range fixture.Requests {
				if i == fixture.SettingsBefore {
					require.NoError(t, e.Configure(fixture.PeerCapacity, fixture.Capacity, 16))
					if fixture.SendCapacity {
						instructions = codec.AppendEncoderCapacity(instructions, fixture.Capacity)
					}
				}
				got, err := e.Encode(request.StreamID, request.Fields, func(b []byte) error { instructions = append(instructions, b...); return nil })
				require.NoError(t, err)
				want, err := hex.DecodeString(request.Block)
				require.NoError(t, err)
				require.Equal(t, want, got, "browser field section %d on stream %d", i, request.StreamID)
				if got[0] != 0 {
					require.Less(t, request.StreamID, uint64(127))
					feedback(t, e, byte(0x80|request.StreamID))
				}
			}
			want, err := hex.DecodeString(fixture.EncoderStream)
			require.NoError(t, err)
			require.Equal(t, want, instructions, "complete browser encoder instruction sequence")
		})
	}
}
